import type { ModuloCO } from './co-intent-seo-content';
export interface IndiceCO { slug: string; h1: string; metaDescription: string; grupo: string; titleTag: string; intro: string; cta: string; ctaTo: string; foto: string; modulo: ModuloCO; hermanas: string[] }
export const INDICE_CO: readonly IndiceCO[] = [{"slug":"firmar-documentos-desde-el-celular","h1":"Firmar documentos desde el celular","metaDescription":"Firma un PDF o un contrato desde tu celular, sin instalar nada y con validez legal en Colombia (Ley 527 de 1999). Envíalo a firmar por WhatsApp o correo.","grupo":"firma","titleTag":"Firmar documentos desde el celular en Colombia","intro":"La mayoría de los contratos en Colombia ya no se firman en una oficina: se firman en un bus, en la fila del banco o en un descanso del trabajo, desde el celular. Lo que falta casi siempre no es la firma, sino la prueba de quién firmó, cuándo y qué documento exacto. Eso es lo que separa una imagen de una firma pegada en un PDF de una firma electrónica que aguanta una discusión.","cta":"Firmar un documento ahora","ctaTo":"/firma-electronica","foto":"/images/contadores/profesional-movil.jpg","modulo":"firma","hermanas":["como-firmar-un-documento-en-word","enviar-documento-a-firmar-por-whatsapp","firmar-en-persona-con-codigo-qr"]},{"slug":"como-firmar-un-documento-en-word","h1":"Cómo firmar un documento de Word","metaDescription":"Firma un documento de Word sin imprimirlo ni escanearlo: súbelo, fírmalo desde el computador o el celular y descárgalo en PDF con certificado de firma.","grupo":"firma","titleTag":"Cómo firmar un documento de Word","intro":"Word sirve para escribir el contrato, pero no para firmarlo. Insertar una imagen de la firma en el documento es lo que hace casi todo el mundo, y es justo lo que menos protege: el archivo se puede seguir editando después, y la imagen se puede copiar a cualquier otro documento. La forma correcta es convertir el Word en un PDF que nadie pueda alterar sin que se note, y firmarlo con registro.","cta":"Subir mi Word y firmarlo","ctaTo":"/firma-electronica","foto":"/images/seo/dashboard-desk.jpg","modulo":"firma","hermanas":["enviar-documento-a-firmar-por-whatsapp","firmar-en-persona-con-codigo-qr","firma-electronica-para-contratos-de-trabajo"]},{"slug":"enviar-documento-a-firmar-por-whatsapp","h1":"Enviar un documento a firmar por WhatsApp","metaDescription":"Manda un contrato a firmar por WhatsApp con un enlace seguro. Quien firma lo hace desde el celular y tú recibes el PDF firmado con certificado.","grupo":"firma","titleTag":"Enviar un documento a firmar por WhatsApp","intro":"En Colombia los negocios se cierran por WhatsApp. El arriendo se acuerda por WhatsApp, la cotización se aprueba por WhatsApp y el contrato de servicios se negocia por WhatsApp. Tiene sentido que la firma también llegue por ahí, pero no como un PDF que la persona tiene que imprimir, firmar, escanear y devolver: como un enlace que se firma en dos minutos.","cta":"Enviar un documento a firmar","ctaTo":"/firma-electronica","foto":"/images/contadores/profesional-movil.jpg","modulo":"firma","hermanas":["firmar-en-persona-con-codigo-qr","firma-electronica-para-contratos-de-trabajo","firma-electronica-para-contratos-de-arriendo"]},{"slug":"firmar-en-persona-con-codigo-qr","h1":"Firmar en persona con código QR","metaDescription":"Muestra un código QR y tu cliente firma el contrato desde su propio celular, ahí mismo. Sin papel, sin tableta prestada y con registro legal.","grupo":"firma","titleTag":"Firmar en persona con código QR","intro":"Hay momentos en que el cliente está ahí, al frente, y hay que firmar ya: al entregar un apartamento, al recibir un vehículo, al cerrar una venta en una feria o al matricular a un estudiante. Pasarle tu celular o una tableta para que firme funciona, pero deja una duda: la firma la hizo él en tu dispositivo. Con un código QR firma en el suyo, y eso cambia la prueba.","cta":"Firmar en persona ahora","ctaTo":"/firma-electronica","foto":"/images/seo/app-man-blue.jpg","modulo":"firma","hermanas":["firma-electronica-para-contratos-de-trabajo","firma-electronica-para-contratos-de-arriendo","convertir-word-en-plantilla"]},{"slug":"firma-electronica-para-contratos-de-trabajo","h1":"Firma electrónica para contratos de trabajo","metaDescription":"Firma contratos laborales en línea con validez en Colombia. Cumple el contrato escrito que exige la reforma laboral (Ley 2466 de 2025) sin papel.","grupo":"firma","titleTag":"Firma electrónica para contratos de trabajo","intro":"Con la reforma laboral, el contrato por escrito dejó de ser una buena práctica y pasó a ser una obligación en varios casos: el de término fijo, el de obra o labor y el del trabajo doméstico. Firmarlos en papel con cada persona nueva es lento, y perderlos en una carpeta es caro. Firmarlos electrónicamente cumple el requisito de forma y deja cada contrato archivado con su prueba.","cta":"Firmar contratos de trabajo en línea","ctaTo":"/my-templates","foto":"/images/seo/office-tablet-woman.jpg","modulo":"firma","hermanas":["firma-electronica-para-contratos-de-arriendo","convertir-word-en-plantilla","firma-con-reconocimiento-facial"]},{"slug":"firma-electronica-para-contratos-de-arriendo","h1":"Firma electrónica para contratos de arriendo","metaDescription":"Firma contratos de arrendamiento de vivienda o local en línea, con cédula verificada y validez legal en Colombia. Arrendador, arrendatario y codeudores.","grupo":"firma","titleTag":"Firma electrónica para contratos de arriendo","intro":"Un contrato de arriendo en Colombia suele tener tres o cuatro firmas: arrendador, arrendatario y uno o dos deudores solidarios, que casi nunca viven en la misma ciudad. Reunirlos en una notaría o mover el papel de casa en casa puede tomar una semana, y en ese tiempo el inmueble sigue vacío. Firmar en línea pone a todos a firmar el mismo día, cada uno desde donde esté.","cta":"Firmar mi contrato de arriendo en línea","ctaTo":"/my-templates","foto":"/images/seo/tablet-sign-business.jpg","modulo":"firma","hermanas":["convertir-word-en-plantilla","firma-con-reconocimiento-facial","firmar-documentos-desde-el-celular"]},{"slug":"convertir-word-en-plantilla","h1":"Convertir un Word en plantilla para llenar","metaDescription":"Sube tu contrato en Word tal como lo usas: encontramos los espacios en blanco y lo convertimos en una plantilla que llenas y envías a firmar en minutos.","grupo":"firma","titleTag":"Convertir un Word en plantilla para llenar","intro":"Todo negocio tiene su contrato en Word: el que hizo el abogado hace años, el que se ha ido corrigiendo con cada cliente. Cada vez que se usa, alguien abre el archivo, busca dónde cambiar el nombre, la cédula y la fecha, se le pasa uno y guarda encima del original. Convertirlo en plantilla significa llenar solo los datos que cambian y no volver a tocar el texto.","cta":"Convertir mi Word en plantilla","ctaTo":"/my-templates","foto":"/images/seo/dashboard-desk.jpg","modulo":"firma","hermanas":["firma-con-reconocimiento-facial","firmar-documentos-desde-el-celular","como-firmar-un-documento-en-word"]},{"slug":"firma-con-reconocimiento-facial","h1":"Firma electrónica con reconocimiento facial","metaDescription":"Pide que quien firma confirme con Face ID, huella o selfie con cédula. Firma electrónica con identidad verificada, válida en Colombia (Ley 527 de 1999).","grupo":"firma","titleTag":"Firma electrónica con reconocimiento facial","intro":"Una firma electrónica vale tanto como la prueba de quién la hizo. Para una autorización sencilla basta un nombre y un trazo; para un pagaré, un contrato de arriendo o la venta de un vehículo, conviene saber con certeza que firmó la persona correcta. El reconocimiento facial o la huella del propio celular, y la selfie con la cédula, son las formas más simples de lograrlo sin pedirle a nadie que vaya a una notaría.","cta":"Firmar con identidad verificada","ctaTo":"/firma-electronica","foto":"/images/seo/app-woman-tech-blue.jpg","modulo":"firma","hermanas":["firmar-documentos-desde-el-celular","como-firmar-un-documento-en-word","enviar-documento-a-firmar-por-whatsapp"]},{"slug":"contrato-de-trabajo-a-termino-indefinido","h1":"Contrato de trabajo a término indefinido","metaDescription":"Qué debe tener un contrato a término indefinido en Colombia tras la reforma laboral (Ley 2466 de 2025). Créalo desde tu modelo y fírmalo en línea.","grupo":"laboral","titleTag":"Contrato de trabajo a término indefinido 2026","intro":"Con la reforma laboral, el contrato a término indefinido dejó de ser una opción entre varias y pasó a ser la regla general en Colombia. Es el contrato que no tiene fecha de terminación pactada: dura mientras subsistan las causas que le dieron origen y la materia del trabajo. Puede celebrarse de palabra, pero hacerlo por escrito es lo que evita las discusiones sobre cargo, salario y jornada que llegan años después.","cta":"Crear mi contrato a término indefinido","ctaTo":"/my-templates","foto":"/images/seo/office-tablet-woman.jpg","modulo":"laboral","hermanas":["contrato-de-trabajo-a-termino-fijo","contrato-por-obra-o-labor","contrato-de-servicio-domestico"]},{"slug":"contrato-de-trabajo-a-termino-fijo","h1":"Contrato de trabajo a término fijo","metaDescription":"Contrato a término fijo en Colombia tras la Ley 2466 de 2025: por escrito, máximo 4 años y preaviso de 30 días. Qué incluir y cómo firmarlo en línea.","grupo":"laboral","titleTag":"Contrato a término fijo: reglas 2026","intro":"El contrato a término fijo sigue existiendo después de la reforma laboral, pero ya no es la forma por defecto de contratar: es una excepción con reglas estrictas. Debe constar por escrito, no puede durar más de cuatro años y, si no se cumplen sus requisitos, se entiende celebrado a término indefinido desde el inicio. Por eso el papel —o el documento electrónico— dejó de ser un trámite y pasó a definir qué contrato tienes.","cta":"Crear mi contrato a término fijo","ctaTo":"/my-templates","foto":"/images/seo/tablet-sign-business.jpg","modulo":"laboral","hermanas":["contrato-por-obra-o-labor","contrato-de-servicio-domestico","contrato-de-aprendizaje"]},{"slug":"contrato-por-obra-o-labor","h1":"Contrato de trabajo por obra o labor","metaDescription":"El contrato por obra o labor debe ser escrito y describir con precisión la labor (Ley 2466 de 2025). Qué incluir y cómo firmarlo desde el celular.","grupo":"laboral","titleTag":"Contrato por obra o labor en Colombia 2026","intro":"El contrato por obra o labor dura lo que dura una tarea concreta: la construcción de una obra, una cosecha, una temporada de ventas, la implementación de un proyecto. Es muy usado en construcción, agro y servicios, y fue uno de los más afectados por la reforma laboral: ahora debe celebrarse por escrito y describir de forma precisa y detallada la labor contratada.","cta":"Crear mi contrato por obra o labor","ctaTo":"/my-templates","foto":"/images/seo/app-man-blue.jpg","modulo":"laboral","hermanas":["contrato-de-servicio-domestico","contrato-de-aprendizaje","carta-de-renuncia-laboral"]},{"slug":"contrato-de-servicio-domestico","h1":"Contrato de servicio doméstico","metaDescription":"Desde la reforma laboral, el trabajo doméstico requiere contrato escrito, también por días u horas (Ley 2466 de 2025). Qué incluir y cómo firmarlo.","grupo":"laboral","titleTag":"Contrato de servicio doméstico 2026","intro":"Durante décadas, la mayoría de las relaciones de trabajo doméstico en Colombia se acordaron de palabra. La reforma laboral cambió eso: hoy toda persona trabajadora del hogar —interna, externa, por días o por horas— debe tener un contrato escrito. Para muchas familias es la primera vez que firman un contrato de trabajo como empleadores, y la buena noticia es que no hace falta ir a ninguna oficina.","cta":"Crear el contrato de servicio doméstico","ctaTo":"/my-templates","foto":"/images/seo/app-woman-blue.jpg","modulo":"laboral","hermanas":["contrato-de-aprendizaje","carta-de-renuncia-laboral","certificado-laboral"]},{"slug":"contrato-de-aprendizaje","h1":"Contrato de aprendizaje","metaDescription":"El contrato de aprendizaje ahora es un contrato laboral especial a término fijo (Ley 2466 de 2025). Qué cambió, qué incluir y cómo firmarlo en línea.","grupo":"laboral","titleTag":"Contrato de aprendizaje tras la reforma laboral","intro":"El contrato de aprendizaje vincula a un estudiante —del SENA, de una institución técnica o tecnológica, o universitario— con una empresa para que aprenda un oficio mientras trabaja. La reforma laboral le devolvió su carácter laboral: hoy es un contrato de trabajo especial a término fijo, con los derechos que eso implica. Para las empresas obligadas a tener aprendices, la reforma cambió los números y también el papeleo.","cta":"Crear el contrato de aprendizaje","ctaTo":"/my-templates","foto":"/images/seo/app-woman-tech-blue.jpg","modulo":"laboral","hermanas":["carta-de-renuncia-laboral","certificado-laboral","otrosi-contrato"]},{"slug":"carta-de-renuncia-laboral","h1":"Carta de renuncia laboral","metaDescription":"Cómo escribir una carta de renuncia voluntaria en Colombia, qué incluir y cómo enviarla firmada con fecha cierta para que no haya dudas sobre tu retiro.","grupo":"laboral","titleTag":"Carta de renuncia laboral: modelo y cómo enviarla","intro":"Renunciar es un derecho del trabajador y no necesita la aceptación del empleador para producir efectos. Lo que sí necesita es claridad: que conste que la decisión fue voluntaria, desde qué fecha y que el empleador la recibió. Una carta corta, firmada y con fecha cierta evita las dos discusiones más comunes al salir de un trabajo: cuándo terminó realmente la relación y si la renuncia fue libre.","cta":"Escribir y enviar mi renuncia","ctaTo":"/generator/resignation-letter","foto":"/images/seo/tablet-review-woman.jpg","modulo":"laboral","hermanas":["certificado-laboral","otrosi-contrato","contrato-de-trabajo-a-termino-indefinido"]},{"slug":"certificado-laboral","h1":"Certificado laboral","metaDescription":"Qué debe incluir un certificado laboral en Colombia, cuándo es obligatorio expedirlo y cómo emitirlo firmado en línea en minutos para cada empleado.","grupo":"laboral","titleTag":"Certificado laboral: qué debe decir y cómo firmarlo","intro":"El certificado laboral es de los documentos que más piden los trabajadores: para un crédito, para arrendar un apartamento, para una visa o para un nuevo empleo. Para el empleador, expedirlo es una obligación cuando el trabajador lo solicita al terminar el contrato, y una cortesía frecuente mientras sigue vinculado. Lo que más demora no es redactarlo, sino conseguir la firma de quien puede firmarlo.","cta":"Emitir certificados laborales","ctaTo":"/my-templates","foto":"/images/seo/dashboard-desk.jpg","modulo":"laboral","hermanas":["otrosi-contrato","contrato-de-trabajo-a-termino-indefinido","contrato-de-trabajo-a-termino-fijo"]},{"slug":"otrosi-contrato","h1":"Otrosí a un contrato","metaDescription":"Qué es un otrosí, cuándo usarlo en un contrato laboral o de arriendo y qué debe incluir. Redáctalo y fírmalo en línea con todas las partes.","grupo":"laboral","titleTag":"Otrosí: qué es y cómo modificar un contrato","intro":"Un otrosí es un documento que modifica, aclara o adiciona un contrato que ya está firmado, sin tener que redactar uno nuevo. Se usa todo el tiempo: para subir un salario, cambiar un cargo, prorrogar un arriendo o ajustar el valor de un servicio. Su nombre viene de la vieja fórmula «otrosí digo», y su regla de oro es simple: lo firman las mismas partes que firmaron el contrato original.","cta":"Crear un otrosí y firmarlo","ctaTo":"/my-templates","foto":"/images/seo/tablet-review-woman.jpg","modulo":"laboral","hermanas":["contrato-de-trabajo-a-termino-indefinido","contrato-de-trabajo-a-termino-fijo","contrato-por-obra-o-labor"]},{"slug":"cuenta-de-cobro","h1":"Cuenta de cobro","metaDescription":"Qué debe tener una cuenta de cobro en Colombia, quién la puede usar y qué documentos la acompañan. Hazla una vez como plantilla y envíala firmada.","grupo":"independientes","titleTag":"Cuenta de cobro: formato y cómo enviarla firmada","intro":"La cuenta de cobro es el documento con el que un independiente que no está obligado a facturar le pide el pago a quien le contrató un servicio. La usan diseñadores, docentes por horas, contratistas del Estado, consultores y miles de personas que trabajan por prestación de servicios. Es sencilla, pero cada mes hay que hacerla de nuevo, y un dato mal puesto puede retrasar el pago semanas.","cta":"Crear mi plantilla de cuenta de cobro","ctaTo":"/my-templates","foto":"/images/seo/dashboard-desk.jpg","modulo":"negocios","hermanas":["contrato-de-prestacion-de-servicios","acuerdo-de-confidencialidad","firmar-documentos-desde-el-celular"]},{"slug":"contrato-de-prestacion-de-servicios","h1":"Contrato de prestación de servicios","metaDescription":"Qué debe tener un contrato de prestación de servicios y cómo evitar que se convierta en un contrato laboral. Créalo desde tu modelo y fírmalo en línea.","grupo":"independientes","titleTag":"Contrato de prestación de servicios en Colombia","intro":"El contrato de prestación de servicios es el acuerdo con el que una persona o empresa contrata a un independiente para un trabajo concreto, con autonomía y sin relación laboral: un diseño, una asesoría, un desarrollo de software, una consultoría. Bien hecho, protege a las dos partes. Mal hecho —o mal ejecutado—, termina en una demanda por contrato realidad.","cta":"Crear mi contrato de prestación de servicios","ctaTo":"/my-templates","foto":"/images/seo/app-man-blue.jpg","modulo":"negocios","hermanas":["acuerdo-de-confidencialidad","cuenta-de-cobro","firmar-documentos-desde-el-celular"]},{"slug":"acuerdo-de-confidencialidad","h1":"Acuerdo de confidencialidad","metaDescription":"Qué debe incluir un acuerdo de confidencialidad válido en Colombia, cuánto debe durar y cómo firmarlo en línea antes de compartir información.","grupo":"independientes","titleTag":"Acuerdo de confidencialidad (NDA) en Colombia","intro":"Antes de mostrarle a alguien tu base de clientes, tus precios, tu código o tu plan de negocio, conviene que firme un acuerdo de confidencialidad. Es un documento corto que dice qué información es confidencial, para qué se puede usar, por cuánto tiempo y qué pasa si se divulga. Firmarlo antes de la primera reunión cuesta minutos; no firmarlo puede costar el negocio.","cta":"Crear mi acuerdo de confidencialidad","ctaTo":"/my-templates","foto":"/images/seo/office-tablet-woman.jpg","modulo":"negocios","hermanas":["cuenta-de-cobro","contrato-de-prestacion-de-servicios","firmar-documentos-desde-el-celular"]},{"slug":"contrato-de-arrendamiento-de-vivienda-urbana","h1":"Contrato de arrendamiento de vivienda urbana","metaDescription":"Qué exige la Ley 820 de 2003 en un contrato de arriendo de vivienda: canon, reajuste por IPC, depósitos prohibidos y codeudores. Fírmalo en línea.","grupo":"inmuebles","titleTag":"Contrato de arrendamiento de vivienda urbana 2026","intro":"El contrato de arrendamiento de vivienda urbana es de los más firmados en Colombia y también de los más discutidos: por el aumento anual, por el depósito, por los daños al entregar y por los codeudores. La Ley 820 de 2003 fija reglas que el contrato no puede contradecir, aunque las partes lo quieran. Conocerlas evita cláusulas que no valen y peleas que se pierden.","cta":"Crear mi contrato de arrendamiento","ctaTo":"/my-templates","foto":"/images/seo/tablet-sign-business.jpg","modulo":"negocios","hermanas":["contrato-de-arrendamiento-de-local-comercial","promesa-de-compraventa-de-inmueble","contrato-de-comodato"]},{"slug":"contrato-de-arrendamiento-de-local-comercial","h1":"Contrato de arrendamiento de local comercial","metaDescription":"El arriendo de local en Colombia se rige por el Código de Comercio: derecho de renovación a los dos años y desahucio de seis meses. Qué incluir y firmarlo.","grupo":"inmuebles","titleTag":"Contrato de arrendamiento de local comercial","intro":"Arrendar un local no es lo mismo que arrendar un apartamento. El contrato de local comercial no se rige por la Ley 820 de 2003, sino por el Código de Comercio, que protege al comerciante que ha construido su negocio en ese lugar. Muchos propietarios lo descubren cuando quieren recuperar el local y se encuentran con que la ley le da al arrendatario derecho a renovar.","cta":"Crear mi contrato de arriendo de local","ctaTo":"/my-templates","foto":"/images/seo/app-man-blue.jpg","modulo":"negocios","hermanas":["promesa-de-compraventa-de-inmueble","contrato-de-comodato","acta-de-entrega-de-inmueble"]},{"slug":"promesa-de-compraventa-de-inmueble","h1":"Promesa de compraventa de inmueble","metaDescription":"Requisitos de una promesa de compraventa válida (Ley 153 de 1887, art. 89): escrita, con fecha para firmar la escritura. Qué incluir y cómo firmarla.","grupo":"inmuebles","titleTag":"Promesa de compraventa de inmueble en Colombia","intro":"Antes de la escritura pública, la venta de una casa o un apartamento suele pasar por una promesa de compraventa: el documento en que comprador y vendedor se obligan a celebrar la venta en una fecha y notaría determinadas, normalmente con una suma de arras. Es un contrato con requisitos estrictos: si le falta uno, puede no producir efecto, y con él se pueden perder las arras.","cta":"Crear mi promesa de compraventa","ctaTo":"/my-templates","foto":"/images/seo/office-tablet-woman.jpg","modulo":"negocios","hermanas":["contrato-de-comodato","acta-de-entrega-de-inmueble","contrato-de-arrendamiento-de-vivienda-urbana"]},{"slug":"contrato-de-comodato","h1":"Contrato de comodato","metaDescription":"El comodato es el préstamo gratuito de un bien para que se use y se devuelva (art. 2200 del Código Civil). Qué incluir y cómo firmarlo en línea.","grupo":"inmuebles","titleTag":"Contrato de comodato: préstamo de un bien","intro":"El comodato es el préstamo gratuito de una cosa para que otra persona la use y la devuelva: un apartamento que se presta a un familiar, una bodega que se cede a una fundación, un equipo que una empresa le presta a un cliente. Como no hay pago, mucha gente no lo pone por escrito. Y precisamente porque no hay pago, recuperar el bien sin documento puede ser difícil.","cta":"Crear mi contrato de comodato","ctaTo":"/my-templates","foto":"/images/seo/app-woman-blue.jpg","modulo":"negocios","hermanas":["acta-de-entrega-de-inmueble","contrato-de-arrendamiento-de-vivienda-urbana","contrato-de-arrendamiento-de-local-comercial"]},{"slug":"acta-de-entrega-de-inmueble","h1":"Acta de entrega de inmueble","metaDescription":"Cómo hacer el acta de entrega de un inmueble arrendado con inventario y estado, y firmarla en el mismo apartamento desde el celular con un código QR.","grupo":"inmuebles","titleTag":"Acta de entrega de inmueble: modelo y firma","intro":"El acta de entrega es el documento que dice en qué estado se recibió o se devolvió un inmueble: paredes, pisos, baños, cocina, llaves, medidores. Se hace al inicio del arriendo y al final, y es la prueba principal cuando hay que discutir quién paga un daño. Hecha a mano en una hoja, se pierde. Hecha con fotos y firmada en el mismo lugar, termina con la discusión antes de que empiece.","cta":"Crear mi acta de entrega","ctaTo":"/my-templates","foto":"/images/seo/app-man-blue.jpg","modulo":"negocios","hermanas":["contrato-de-arrendamiento-de-vivienda-urbana","contrato-de-arrendamiento-de-local-comercial","promesa-de-compraventa-de-inmueble"]},{"slug":"pagare-con-carta-de-instrucciones","h1":"Pagaré con carta de instrucciones","metaDescription":"Requisitos del pagaré y de la carta de instrucciones en Colombia (arts. 621, 622 y 709 del Código de Comercio) y qué saber antes de firmarlo en línea.","grupo":"dinero","titleTag":"Pagaré con carta de instrucciones: requisitos","intro":"El pagaré es el título valor más usado en Colombia para respaldar una deuda: un préstamo entre personas, la venta de un bien a plazos, un crédito de un almacén. Cuando se firma con espacios en blanco —el valor final o la fecha de vencimiento—, debe ir con una carta de instrucciones que diga cómo se llenarán. Un pagaré bien hecho se puede cobrar; uno mal hecho es solo una hoja con una firma.","cta":"Crear un pagaré con instrucciones","ctaTo":"/my-templates","foto":"/images/seo/dashboard-desk.jpg","modulo":"dinero","hermanas":["letra-de-cambio","contrato-de-compraventa-de-vehiculo","firmar-documentos-desde-el-celular"]},{"slug":"letra-de-cambio","h1":"Letra de cambio","metaDescription":"Requisitos de la letra de cambio en Colombia (art. 671 del Código de Comercio), cómo se llena y cuándo conviene más un pagaré o un contrato de préstamo.","grupo":"dinero","titleTag":"Letra de cambio: cómo se llena y requisitos","intro":"La letra de cambio es el título valor de los préstamos entre conocidos en Colombia: la que se compra en la papelería, se llena a mano y se guarda en un cajón. Es útil y tiene fuerza legal, pero se llena mal con mucha frecuencia, y una letra con un requisito faltante puede no servir para cobrar. Saber cómo se llena es la diferencia entre un respaldo real y un papel.","cta":"Crear un documento de préstamo","ctaTo":"/my-templates","foto":"/images/seo/tablet-review-woman.jpg","modulo":"dinero","hermanas":["contrato-de-compraventa-de-vehiculo","pagare-con-carta-de-instrucciones","firmar-documentos-desde-el-celular"]},{"slug":"contrato-de-compraventa-de-vehiculo","h1":"Contrato de compraventa de vehículo","metaDescription":"Qué incluir en la compraventa de un carro o moto en Colombia y por qué el traspaso en el RUNT es urgente desde 2026. Firma el contrato en línea.","grupo":"dinero","titleTag":"Contrato de compraventa de vehículo 2026","intro":"Vender un carro o una moto entre particulares en Colombia tiene dos momentos: el contrato de compraventa, en el que se acuerda la venta y se entrega el vehículo, y el traspaso ante el organismo de tránsito, que cambia el propietario en el RUNT. El error más caro es creer que con el primero basta: mientras no se haga el traspaso, el vendedor sigue siendo el responsable ante la ley.","cta":"Crear mi contrato de compraventa de vehículo","ctaTo":"/my-templates","foto":"/images/seo/app-man-blue.jpg","modulo":"dinero","hermanas":["pagare-con-carta-de-instrucciones","letra-de-cambio","firmar-documentos-desde-el-celular"]},{"slug":"contrato-de-mandato","h1":"Contrato de mandato","metaDescription":"El mandato es el encargo de gestionar un negocio por cuenta de otro (art. 2142 del Código Civil). Usos comunes, qué incluir y cómo firmarlo en línea.","grupo":"tramites","titleTag":"Contrato de mandato: qué es y cómo hacerlo","intro":"El contrato de mandato es el que celebras cuando le encargas a otra persona que haga algo por ti: un tramitador que hace el traspaso de tu vehículo, un administrador que gestiona tus arriendos, un amigo que vende algo en tu nombre. Es un contrato cotidiano y, precisamente por eso, muchas veces se hace sin papel, hasta que el encargado hace algo que no se le pidió.","cta":"Crear mi contrato de mandato","ctaTo":"/my-templates","foto":"/images/seo/office-tablet-woman.jpg","modulo":"dinero","hermanas":["poder-especial","autorizacion-tratamiento-de-datos-personales","firmar-documentos-desde-el-celular"]},{"slug":"poder-especial","h1":"Poder especial","metaDescription":"Cómo otorgar un poder especial en Colombia para un trámite o un proceso judicial, y cuándo vale sin firma manuscrita (Ley 2213 de 2022, artículo 5).","grupo":"tramites","titleTag":"Poder especial: modelo y cómo otorgarlo","intro":"Un poder especial autoriza a otra persona a actuar en tu nombre para un asunto determinado: reclamar un documento, hacer un trámite, vender un bien o representarte en un proceso judicial. Es especial porque se limita a ese asunto, a diferencia del poder general. Para los poderes judiciales, la ley colombiana simplificó mucho el trámite desde la virtualidad: ya no siempre hace falta ir a una notaría.","cta":"Crear y firmar un poder especial","ctaTo":"/my-templates","foto":"/images/seo/tablet-review-woman.jpg","modulo":"dinero","hermanas":["autorizacion-tratamiento-de-datos-personales","contrato-de-mandato","firmar-documentos-desde-el-celular"]},{"slug":"autorizacion-tratamiento-de-datos-personales","h1":"Autorización de tratamiento de datos personales","metaDescription":"Cómo obtener la autorización previa, expresa e informada que exige la Ley 1581 de 2012 y guardar la prueba. Formato y firma en línea para tus clientes.","grupo":"tramites","titleTag":"Autorización de tratamiento de datos personales","intro":"Cualquier negocio que recoja nombres, cédulas, teléfonos o correos de sus clientes, empleados o estudiantes está tratando datos personales. La ley colombiana exige que, antes de hacerlo, obtenga una autorización previa, expresa e informada de cada titular, y que pueda demostrarla después. No basta con tenerla: hay que poder probar que se obtuvo.","cta":"Crear mi formato de autorización","ctaTo":"/my-templates","foto":"/images/seo/app-woman-tech-blue.jpg","modulo":"dinero","hermanas":["contrato-de-mandato","poder-especial","firmar-documentos-desde-el-celular"]}];
